// Generated by scripts/build-zalo-worker.mjs; no credentials.
import {createClient} from 'npm:@supabase/supabase-js@2.118.0';
// Only this backend module contacts Zalo; no response bodies or credentials are logged.
export async function sendReport(item,{fetchImpl=fetch,timeoutMs=10000}={}) {
  if (!item || typeof item.token!=='string' || !/^[A-Za-z0-9:_-]{10,512}$/.test(item.token)
    || typeof item.chatId!=='string' || item.chatId.length<1 || item.chatId.length>200 || /[\x00-\x1f\x7f]/.test(item.chatId)
    || typeof item.text!=='string' || item.text.length<1 || item.text.length>2000)
    return {outcome:'rejected',messageId:null,errorCode:'INVALID_CONFIG'};
  try {
    const chatIds = item.chatId.split(',').map(s=>s.trim()).filter(Boolean);
    let lastId = null;
    let anyRejected = false;
    for (const cid of chatIds) {
      const response=await fetchImpl(`https://bot-api.zaloplatforms.com/bot${item.token}/sendMessage`,{
        method:'POST',headers:{'Content-Type':'application/json'},redirect:'error',
        body:JSON.stringify({chat_id:cid,text:item.text}),signal:AbortSignal.timeout(timeoutMs)
      });
      const body=await response.json();
      const id=body?.result?.message_id;
      if(response.ok && body?.ok===true && typeof id==='string' && id.length>0 && id.length<=200 && !/[\x00-\x1f\x7f]/.test(id)) {
        lastId = id;
      } else if(response.status<500 && body?.ok===false) {
        anyRejected = true;
      }
    }
    if (lastId) return {outcome:'sent',messageId:lastId,errorCode:null};
    if (anyRejected) return {outcome:'rejected',messageId:null,errorCode:'ZALO_REJECTED'};
  }catch{/* Timeout/connection loss/invalid response could occur after Zalo accepted the message. */}
  return {outcome:'unknown',messageId:null,errorCode:'ZALO_UNKNOWN'};
}

export async function runDelivery(db,options={}) {
  const claimed=await db.rpc('zalo_claim_delivery');
  if(claimed.error) throw new Error('ZALO_DATABASE_UNAVAILABLE');
  if(!claimed.data) return {status:'idle'};
  const item=claimed.data,result=await sendReport(item,options);
  const finished=await db.rpc('zalo_finish_delivery',{p_id:item.id,p_lease_id:item.leaseId,
    p_outcome:result.outcome,p_message_id:result.messageId,p_error_code:result.errorCode});
  // Never retry sendMessage after a failed acknowledgment write.
  if(finished.error || finished.data!==true) return {status:'needs_reconciliation'};
  return {status:result.outcome};
}

export function createHandler({createClient,env,sendOptions={}}) {
  return async request=>{
    const reply=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
    if(request.headers.has('origin')) return reply({success:false},403);
    if(request.method!=='POST') return reply({success:false},405);
    const secret=request.headers.get('x-zalo-worker-secret');
    if(!secret || !/^[0-9a-f]{64}$/.test(secret))return reply({success:false},401);
    const url=env('SUPABASE_URL'),key=env('SUPABASE_SERVICE_ROLE_KEY');
    if(!url || !key)return reply({success:false},503);
    try{
      const db=createClient(url,key,{auth:{persistSession:false,autoRefreshToken:false}});
      const authorized=await db.rpc('zalo_authorize_worker',{p_secret:secret});
      if(authorized.error)return reply({success:false},503);
      if(authorized.data!==true)return reply({success:false},401);
      return reply({success:true,...await runDelivery(db,sendOptions)});
    }catch{return reply({success:false,message:'Worker chưa hoàn tất; kiểm tra trạng thái trước khi xử lý lại.'},503);}
  };
}

Deno.serve(createHandler({createClient,env:name=>Deno.env.get(name)}));
